CREATE TABLE usuarios (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255),email VARCHAR(255) UNIQUE,password VARCHAR(255) NOT NULL,rol ENUM('ROLE_USER','ROLE_ADMIN','ROLE_GUIA') NOT NULL,activo BIT NOT NULL);
CREATE TABLE tours (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(255) NOT NULL,descripcion VARCHAR(1000),ciudad VARCHAR(255),pais VARCHAR(255),imagen_url VARCHAR(255),precio BIGINT,latitud DOUBLE,longitud DOUBLE,activo BIT);
CREATE TABLE reservas(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,email_cliente VARCHAR(255),nombre_cliente VARCHAR(255),tour_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,monto DECIMAL(38,2),estado ENUM('PENDIENTE','PAGADA','CANCELADA','FINALIZADA','FALLIDA','EN_CURSO'),metodo_pago ENUM('TARJETA','PSE','EFECTIVO','TRANSFERENCIA','NEQUI','DAVIPLATA'),stripe_payment_intent_id VARCHAR(255) UNIQUE,fecha_creacion DATETIME(6),guia_id BIGINT,payment_provider VARCHAR(255),external_payment_id VARCHAR(255),payment_redirect_url VARCHAR(255),payment_reference VARCHAR(255),FOREIGN KEY(tour_id) REFERENCES tours(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(guia_id) REFERENCES usuarios(id));
CREATE TABLE refresh_token(id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL UNIQUE,token VARCHAR(255),expiry_date DATETIME(6),FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
